const entrada = $input.first().json;

// O Error Trigger entrega DOIS formatos: falha de execucao (chave `execution`) e falha de
// gatilho ou de ativacao (chave `trigger`), e no segundo nao existe id de execucao. Ler so
// um dos dois faz metade das falhas chegarem vazias na fila_morta, que e o mesmo que nao
// ter alerta.
const execucao = entrada.execution || {};
const gatilho = entrada.trigger || {};
const fluxo = entrada.workflow || {};
const erro = execucao.error || gatilho.error || {};

const nome_do_fluxo = fluxo.name || 'desconhecido';
const mensagem = [erro.name, erro.message].filter(Boolean).join(': ') || 'falha sem detalhe';
const no_que_falhou = execucao.lastNodeExecuted || (erro.node && erro.node.name) || null;

const payload = {
  workflow_id: fluxo.id || null,
  workflow: nome_do_fluxo,
  execucao_id: execucao.id || null,
  execucao_url: execucao.url || null,
  modo: execucao.mode || (entrada.trigger ? 'gatilho' : null),
  retentativa_de: execucao.retryOf || null,
  no_que_falhou: no_que_falhou,
  // Cinco linhas de stack: o suficiente para achar o arquivo e a linha, pouco o bastante
  // para a fila_morta nao virar deposito de log.
  erro_stack: String(erro.stack || '').split('\n').slice(0, 5).join('\n')
};

const texto = [
  'Workflow: ' + nome_do_fluxo + ' (' + (fluxo.id || 'sem id') + ')',
  'No que falhou: ' + (no_que_falhou || 'nao informado'),
  'Execucao: ' + (execucao.id || 'nao informada'),
  'Link: ' + (execucao.url || 'nao informado'),
  '',
  'Erro: ' + mensagem,
  '',
  'A falha foi gravada em public.fila_morta. Depois de resolver, marque revisado_em.'
].join('\n');

// tenant_id fica nulo: a falha pode ocorrer antes de existir barbearia (webhook de
// pagamento que nao normaliza), e a coluna e nulavel justamente por isso. Inventar dono
// aqui esconderia a falha do inquilino certo.
return [{ json: {
  tenant_id: null,
  origem: 'n8n:' + nome_do_fluxo,
  evento: 'workflow.falhou',
  erro: mensagem,
  payload: payload,
  assunto: '[FastChair] falha no workflow ' + nome_do_fluxo,
  texto: texto
} }];
